import sveltekit from '../.svelte-kit/cloudflare/_worker.js';
import { handleEmail } from './handlers/email';
import { handleScheduled } from './handlers/scheduled';
import {handlePublicOAuth} from '../src/lib/server/core/oauth-http';
import {handleDeliveryBridge,handleDeliveryQueue} from './handlers/delivery-events';
import type { RuntimeEnv } from '../src/lib/server/core/types';

export default {
  async fetch(request,env,ctx) {
    const delivery=await handleDeliveryBridge(request,env);
    if(delivery)return delivery;
    // OAuth's cookie-free public protocol endpoints must accept PKCE form posts before Kit's browser CSRF gate.
    const requestId=crypto.randomUUID(),oauth=await handlePublicOAuth(request,env,requestId);
    if(oauth) {oauth.headers.set('X-Request-Id',requestId);return oauth;}
    return sveltekit.fetch!(request,env,ctx);
  },
  email(message,env) { return handleEmail(message,env); },
  scheduled(controller,env) { return handleScheduled(controller,env); },
  queue(batch,env) { return handleDeliveryQueue(batch,env); }
} satisfies ExportedHandler<RuntimeEnv>;
